import{_ as d,C as s,o as h,c as l,j as t,a,E as o,ao as r}from"./chunks/framework.ucUddl5u.js";const b=JSON.parse('{"title":"The Interface","description":"","frontmatter":{},"headers":[],"relativePath":"guide/interface.md","filePath":"guide/interface.md","lastUpdated":null}'),c={name:"guide/interface.md"};function g(p,e,u,f,m,w){const i=s("DemoShot"),n=s("DemoLoop");return h(),l("div",null,[e[0]||(e[0]=t("h1",{id:"The-Interface",tabindex:"-1"},[a("The Interface "),t("a",{class:"header-anchor",href:"#The-Interface","aria-label":'Permalink to "The Interface {#The-Interface}"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("Ship of Tools is three columns: navigation, preview and agent. The bottom drawer, when open, sits under the navigation and preview columns; the agent column always runs the full height. The columns are fixed in role; the drawer swaps between four contents. Every pane is keyboard-driven and every chord is rebindable; see "),t("a",{href:"./../ref/keybindings"},"Keybindings"),a(".")],-1)),o(i,{path:"layout-labelled.png",caption:"The default layout with the Julia drawer open."}),e[2]||(e[2]=r('<p><code>Ctrl+J</code>, <code>Ctrl+T</code>, <code>Ctrl+M</code> and <code>F1</code> swap the REPL, Terminal, Monitor and Help into the drawer. Column order, widths and the drawer height come from the <a href="/ship-of-tools/dev/ref/config#layout">layout preset</a>; the portrait preset drops the agent column.</p><p>This page walks each pane in turn — what it is, what fills it, and the keys that drive it — and links out to the guide behind it. For a first-session walkthrough, see <a href="./../start/tour">Your first session</a>.</p>',2)),o(n,{name:"help",caption:"The Help drawer (Ctrl+? twice): Tab widens the scope to all panes, typing zoom filters the actions, Down steps through them."}),e[3]||(e[3]=r('<h2 id="The-panes" tabindex="-1">The panes <a class="header-anchor" href="#The-panes" aria-label="Permalink to &quot;The panes {#The-panes}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Pane</th><th style="text-align:right;">Position</th><th style="text-align:right;">What it is</th><th style="text-align:right;">Deep dive</th></tr></thead><tbody><tr><td style="text-align:right;"><a href="/ship-of-tools/dev/guide/interface#The-Navigation-Pane">Navigation</a></td><td style="text-align:right;">left column</td><td style="text-align:right;">the mode tree — a collapsible outline whose root you switch with a hotkey</td><td style="text-align:right;"><a href="./modes">Modes</a></td></tr><tr><td style="text-align:right;"><a href="/ship-of-tools/dev/guide/interface#The-Preview-Pane">Preview</a></td><td style="text-align:right;">middle column</td><td style="text-align:right;">the selected entry, rendered</td><td style="text-align:right;"><a href="./previews">Previews</a></td></tr><tr><td style="text-align:right;"><a href="/ship-of-tools/dev/guide/interface#The-Agent-Pane">Agent</a></td><td style="text-align:right;">right column</td><td style="text-align:right;">the session&#39;s agent (Claude Code, Codex or a plain shell)</td><td style="text-align:right;"><a href="./agents">Running several agents</a></td></tr><tr><td style="text-align:right;"><a href="/ship-of-tools/dev/guide/interface#The-REPL-Pane">REPL</a></td><td style="text-align:right;">bottom drawer</td><td style="text-align:right;">the persistent Julia session, figures inline</td><td style="text-align:right;"><a href="./repl">The REPL</a></td></tr></tbody></table><h2 id="The-bottom-drawer" tabindex="-1">The bottom drawer <a class="header-anchor" href="#The-bottom-drawer" aria-label="Permalink to &quot;The bottom drawer {#The-bottom-drawer}&quot;">​</a></h2><p>The bottom drawer is shared by the REPL, the Terminal, the Monitor and Help, each with its own global toggle. Pressing a second toggle swaps the content in place rather than stacking:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Drawer</th><th style="text-align:right;">Toggle</th><th style="text-align:right;">What it is</th></tr></thead><tbody><tr><td style="text-align:right;"><a href="/ship-of-tools/dev/guide/interface#The-REPL-Pane">REPL</a></td><td style="text-align:right;"><code>Ctrl+J</code></td><td style="text-align:right;">persistent Julia session; values, stdout, and figures stream back as structured frames</td></tr><tr><td style="text-align:right;"><a href="/ship-of-tools/dev/guide/interface#The-Terminal-Drawer">Terminal</a></td><td style="text-align:right;"><code>Ctrl+T</code></td><td style="text-align:right;">a local OS shell on the <em>frontend</em> machine — canonical use is SSHing out to backend hosts</td></tr><tr><td style="text-align:right;"><a href="/ship-of-tools/dev/guide/interface#The-Monitor-Drawer">Monitor</a></td><td style="text-align:right;"><code>Ctrl+M</code></td><td style="text-align:right;">CPU / GPU / RAM history across your configured hosts</td></tr><tr><td style="text-align:right;"><a href="/ship-of-tools/dev/guide/interface#Help-drawer">Help</a></td><td style="text-align:right;"><code>F1</code>, or <code>Ctrl+?</code> twice</td><td style="text-align:right;">the focused pane&#39;s actions and their bindings, searchable</td></tr></tbody></table><p>Drawer toggles are <strong>global</strong> — they fire even when another pane holds focus.</p><h2 id="Help-drawer" tabindex="-1">Help drawer <a class="header-anchor" href="#Help-drawer" aria-label="Permalink to &quot;Help drawer {#Help-drawer}&quot;">​</a></h2><p><strong>F1</strong> opens the Help drawer for the pane you were using. Type to search, use arrows to select an action, Tab to browse all panes, and Enter to open its manual. Escape restores the previous drawer and focus. The Help view preserves its source context while you read; switching away leaves Julia and terminal processes running.</p><h2 id="Focus-and-layout" tabindex="-1">Focus and layout <a class="header-anchor" href="#Focus-and-layout" aria-label="Permalink to &quot;Focus and layout {#Focus-and-layout}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Action</th><th style="text-align:right;">Key</th></tr></thead><tbody><tr><td style="text-align:right;">Move focus between panes (spatial)</td><td style="text-align:right;"><code>Ctrl+Arrow</code></td></tr><tr><td style="text-align:right;">Navigate within the focused pane</td><td style="text-align:right;">plain <code>Arrow</code></td></tr><tr><td style="text-align:right;">Maximize the focused pane</td><td style="text-align:right;"><code>Alt+=</code></td></tr><tr><td style="text-align:right;">Wide-preview: hide the LLM column, hand its width to the preview</td><td style="text-align:right;"><code>Alt++</code></td></tr><tr><td style="text-align:right;">Restore the layout, one layer per press (un-maximize, then exit wide-preview)</td><td style="text-align:right;"><code>Esc</code> (only while maximized or in wide-preview)</td></tr><tr><td style="text-align:right;">Switch to the next / previous session</td><td style="text-align:right;"><code>Shift+Arrow</code></td></tr><tr><td style="text-align:right;">Temporary pane actions / promote to Help drawer</td><td style="text-align:right;"><code>Ctrl+?</code> / press again</td></tr><tr><td style="text-align:right;">Open Help directly</td><td style="text-align:right;"><code>F1</code></td></tr></tbody></table><p><code>Alt+=</code> maximizes the focused pane, <code>Escape</code> restores.</p><p>Plain arrows, <code>Ctrl+Arrow</code>, and <code>Shift+Arrow</code> are scoped so they do not conflict: <code>Shift+Arrow</code> switches sessions, except in a text editor, where it extends the selection, and in an image preview, where <code>Shift+Up</code> and <code>Shift+Down</code> zoom. The authoritative, build-current chord list is in <a href="./../ref/keybindings">Keybindings</a>; when in doubt, <code>Ctrl+?</code> (or <code>F1</code>) is the source of truth.</p><h2 id="The-Navigation-Pane" tabindex="-1">The Navigation Pane <a class="header-anchor" href="#The-Navigation-Pane" aria-label="Permalink to &quot;The Navigation Pane {#The-Navigation-Pane}&quot;">​</a></h2><p><em>Left column.</em> The navigation pane is the <strong>mode tree</strong> — a single collapsible outline (a parent context, the current level, and its children, shown through indentation and disclosure carets) that you walk with the arrow keys. It is the pane you steer from; the <a href="/ship-of-tools/dev/guide/interface#The-Preview-Pane">Preview pane</a> reflects whatever node the cursor is on.</p>',14)),o(i,{name:"nav-files",caption:"Files mode with src/DemoProject.jl selected; its source in the preview."}),e[4]||(e[4]=r('<h3 id="What-fills-it" tabindex="-1">What fills it <a class="header-anchor" href="#What-fills-it" aria-label="Permalink to &quot;What fills it {#What-fills-it}&quot;">​</a></h3><p>A <strong>mode</strong> is a switchable root for this tree. A hotkey swaps which tree fills the columns, and <strong>cursor position is preserved per mode</strong>, so jumping between modes and back lands you where you left each one. The modes bound today:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Mode</th><th style="text-align:right;">Roots the tree at</th></tr></thead><tbody><tr><td style="text-align:right;"><code>f</code></td><td style="text-align:right;">Files</td><td style="text-align:right;">the project filesystem</td></tr><tr><td style="text-align:right;"><code>m</code></td><td style="text-align:right;">Modules</td><td style="text-align:right;">modules and their definitions (types, functions, macros and submodules), read-only, from <code>JuliaSyntax.jl</code></td></tr><tr><td style="text-align:right;"><code>s</code></td><td style="text-align:right;">Sessions</td><td style="text-align:right;">the workspaces this backend is hosting</td></tr><tr><td style="text-align:right;"><code>h</code></td><td style="text-align:right;">Hosts</td><td style="text-align:right;">the remote hosts you can target</td></tr></tbody></table><p>The mode keys are plain single characters, so they are <strong>scoped to navigation focus</strong>: typing <code>f</code> into the REPL or a prompt inserts an <code>f</code>, it does not switch modes. The full conceptual mode set (Project, Types, Math, Outputs, Agents) and what is built today is on the <a href="./modes">Modes</a> page.</p><h3 id="Driving-it" tabindex="-1">Driving it <a class="header-anchor" href="#Driving-it" aria-label="Permalink to &quot;Driving it {#Driving-it}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Action</th><th style="text-align:right;">Key</th></tr></thead><tbody><tr><td style="text-align:right;">Move up/down the tree</td><td style="text-align:right;"><code>↑</code> / <code>↓</code></td></tr><tr><td style="text-align:right;">Descend into the cursored node</td><td style="text-align:right;"><code>→</code></td></tr><tr><td style="text-align:right;">Back up a level</td><td style="text-align:right;"><code>←</code></td></tr><tr><td style="text-align:right;">Switch nav mode</td><td style="text-align:right;"><code>f</code> / <code>m</code> / <code>s</code> / <code>h</code></td></tr><tr><td style="text-align:right;">Focus this pane from elsewhere</td><td style="text-align:right;"><code>Ctrl+Arrow</code> (spatial)</td></tr><tr><td style="text-align:right;">Copy the cursored file&#39;s path to the clipboard</td><td style="text-align:right;"><code>c</code></td></tr></tbody></table><h3 id="The-lines-around-the-tree" tabindex="-1">The lines around the tree <a class="header-anchor" href="#The-lines-around-the-tree" aria-label="Permalink to &quot;The lines around the tree {#The-lines-around-the-tree}&quot;">​</a></h3><ul><li><p><strong><code>status:</code></strong> above the tree usually reads <code>connected · &lt;host&gt;:&lt;workspace&gt; · rev N</code>: the connection, the active workspace, and the last revision of backend state the window has received. An action such as a pin replaces it with a short message (<code>pinned · &lt;path&gt;</code>).</p></li><li><p><strong><code>annotation:</code></strong> below the tree is the <a href="./concept-layer">concept annotation</a> status of the cursored entry: <code>present</code>, <code>(none)</code> when no annotation file exists for it, <code>loading</code>, or <code>(no target for this row)</code> for rows such as sessions that cannot carry one.</p></li><li><p><strong><code>key:</code></strong> shows the last key the window received, which helps when a binding does not do what you expect.</p></li><li><p>In Sessions mode, a tag in brackets after a session&#39;s name is the state of its supervised process: <code>[starting]</code>, <code>[ready]</code>, <code>[ending]</code>, <code>[stopped]</code> (no process has run for it yet), <code>[terminal]</code> (it ended and will not restart), or <code>[unreachable]</code> (the backend could not query it). The row is coloured by the agent&#39;s <a href="./../concepts/work-state">work state</a> and ends with the reason the agent last reported.</p></li><li><p>The bottom border of the window shows the frontend (<code>fe</code>) and backend (<code>be</code>) versions.</p></li></ul><p>Modes are a <strong>planned plugin surface</strong>: the design is a <code>Mode</code> subtype with <code>tree_root</code> / <code>tree_children</code> / <code>preview_for</code> methods — the core modes shipping the same way, with no privileged path. Today the nav roots are fixed (the four above) and built into the frontend and backend; the mode-plugin seam is not yet wired. See <a href="./../extend/mode">Writing a Mode Plugin</a> and <a href="./../extend/abi">The Dispatch ABI</a>.</p><h2 id="The-Preview-Pane" tabindex="-1">The Preview Pane <a class="header-anchor" href="#The-Preview-Pane" aria-label="Permalink to &quot;The Preview Pane {#The-Preview-Pane}&quot;">​</a></h2><p><em>Middle column.</em> The preview pane renders whatever the <a href="/ship-of-tools/dev/guide/interface#The-Navigation-Pane">Navigation pane</a> cursor is on, at the fidelity appropriate to its type — markdown rendered, PNGs shown, <code>.jl</code> syntax-highlighted, PDFs paged, video as a poster frame.</p>',11)),o(i,{name:"preview-math",caption:"A markdown note with typeset math and a table of each leg's bearing."}),e[5]||(e[5]=r('<h3 id="What-fills-it-2" tabindex="-1">What fills it <a class="header-anchor" href="#What-fills-it-2" aria-label="Permalink to &quot;What fills it {#What-fills-it-2}&quot;">​</a></h3><p>The backend first asks the Julia kernel: a <code>FileType</code> plugin claims the path with <code>matches</code> and returns a <code>PreviewPayload</code> from <code>preview</code>. When no plugin claims it, the backend reads the file itself; that is how raster images and plain text are served. The payload&#39;s <code>mime</code> tells the frontend which renderer to use; the bytes are opaque to Rust, so adding a format is a <strong>Julia-only</strong> change. A sampling of the built-ins:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Kind</th><th style="text-align:right;">Rendered as</th></tr></thead><tbody><tr><td style="text-align:right;"><code>.jl</code></td><td style="text-align:right;">syntax-highlighted source (tokenized kernel-side, no client re-parsing)</td></tr><tr><td style="text-align:right;"><code>.md</code></td><td style="text-align:right;">rendered markdown, including inline math</td></tr><tr><td style="text-align:right;"><code>.json</code> / <code>.toml</code> / <code>.txt</code></td><td style="text-align:right;">plain text (JSON/TOML pretty-print / colour planned)</td></tr><tr><td style="text-align:right;"><code>.pdf</code></td><td style="text-align:right;">one rasterized page; with the preview focused (<code>Ctrl+Right</code>) <code>n</code> / <code>p</code> turn pages</td></tr><tr><td style="text-align:right;">video (<code>.mp4</code>, <code>.webm</code>, …)</td><td style="text-align:right;">a poster frame; <code>o</code> opens playback in the browser</td></tr></tbody></table><p>The full table — every built-in type and its MIME — is on the <a href="./previews">Previews</a> page.</p><h3 id="Beyond-static-rendering" tabindex="-1">Beyond static rendering <a class="header-anchor" href="#Beyond-static-rendering" aria-label="Permalink to &quot;Beyond static rendering {#Beyond-static-rendering}&quot;">​</a></h3><ul><li><strong>Pin a file.</strong> <code>p</code> keeps a file in the preview pane while you browse elsewhere in the tree; <code>p</code> again unpins it and the cursor returns to it. A pinned preview still updates as the file changes on disk.</li></ul>',6)),o(n,{name:"pin",caption:"Pressing p pins the preview to src/DemoProject.jl while the cursor moves on; pressing p again unpins it; the cursor returns to the pinned file, and the preview then follows the cursor."}),e[6]||(e[6]=r('<ul><li><p><strong>Opens in the browser, not the pane.</strong> Interactive HTML, Pluto notebooks, and Quarto documents pop out to the OS browser through the backend connection, local or remote, rather than rendering in-pane; the source still previews as text. Same policy as video.</p></li><li><p><strong>Capture a region for the LLM.</strong> On a raster image you can crop a zoomed region and hand it straight to the agent — &quot;what&#39;s the artifact here?&quot;. The crop is taken from the source image on the backend, so the agent sees exactly what you do.</p></li><li><p><strong>No silent blanks.</strong> When an external tool is missing (ffmpeg, poppler), the plugin returns a <code>text/markdown</code> note explaining the gap instead of an empty pane.</p></li></ul><h2 id="The-Agent-Pane" tabindex="-1">The Agent Pane <a class="header-anchor" href="#The-Agent-Pane" aria-label="Permalink to &quot;The Agent Pane {#The-Agent-Pane}&quot;">​</a></h2><p><em>Right column.</em> The agent pane holds the session&#39;s agent: Claude Code, Codex or a plain shell. Its title bar reads <code>llm</code>. You describe what you want; the agent reads code, writes code, and runs code in the <a href="/ship-of-tools/dev/guide/interface#The-REPL-Pane">REPL</a> to get there. See <a href="./orchestrator">Agent sessions</a>.</p><h3 id="What-fills-it-3" tabindex="-1">What fills it <a class="header-anchor" href="#What-fills-it-3" aria-label="Permalink to &quot;What fills it {#What-fills-it-3}&quot;">​</a></h3><p>Each session runs Claude Code, Codex or a plain shell. A session belongs to a workspace on the <strong>backend daemon</strong>, so it sits alongside project state and <strong>survives a frontend restart</strong>.</p><p>Several sessions run concurrently — one per workspace/session, across machines — coordinated over the <a href="./messaging">inter-agent communication system</a>. You start and switch them from <a href="/ship-of-tools/dev/guide/interface#The-Navigation-Pane">Sessions mode</a> (<code>s</code>); cycle the active workspace with <code>Shift+Arrow</code>. What is still deferred is a dedicated in-UI <strong>Agents mode</strong> (a tasks → timeline → step-detail view).</p><h3 id="How-it-acts" tabindex="-1">How it acts <a class="header-anchor" href="#How-it-acts" aria-label="Permalink to &quot;How it acts {#How-it-acts}&quot;">​</a></h3><ul><li><p><strong>Its own tools, plus a few skills.</strong> The agent brings its own tools and context management. The installer adds skills that let it run code in the workspace REPL (<code>sot-fe repl</code>), show a file in your preview pane (<code>show-result</code>) and message other sessions, and hooks that report its work state. See <a href="/ship-of-tools/dev/guide/repl#agents-repl">How agents use the REPL</a>.</p></li><li><p><strong>Permissions come from the agent CLI.</strong> Sessions launch Claude Code with <code>--permission-mode auto</code> and Codex with <code>--dangerously-bypass-approvals-and-sandbox --dangerously-bypass-hook-trust</code>; Ship of Tools adds no permission layer of its own. See <a href="/ship-of-tools/dev/guide/orchestrator#Permission-mode">Agent sessions</a>.</p></li></ul><h3 id="Hand-it-a-file,-or-a-crop-of-an-image" tabindex="-1">Hand it a file, or a crop of an image <a class="header-anchor" href="#Hand-it-a-file,-or-a-crop-of-an-image" aria-label="Permalink to &quot;Hand it a file, or a crop of an image {#Hand-it-a-file,-or-a-crop-of-an-image}&quot;">​</a></h3><p>In Files mode, <code>c</code> copies the selected file&#39;s path to the clipboard for pasting into the agent&#39;s prompt.</p>',10)),o(n,{name:"copy",caption:"Pressing c in Files mode copies the selected file's path; Ctrl+V pastes it into the Claude Code session in the agent pane; asked what the script does, it answers in one sentence."}),e[7]||(e[7]=t("p",null,[a("With the preview focused ("),t("code",null,"Ctrl+Right"),a("), "),t("code",null,"c"),a(" on a zoomed image crops the visible region instead and drops a ready-to-send line into the agent pane's input, naming the source file, the region, and the crop saved under "),t("code",null,".sot/captures/"),a(".")],-1)),o(n,{name:"crop",caption:"With the preview focused, pressing c on a zoomed figure sends the visible region to the Claude Code session in the agent pane; asked which leg in it is the shortest, the agent reads the answer off the crop."}),e[8]||(e[8]=r('<h2 id="The-REPL-Pane" tabindex="-1">The REPL Pane <a class="header-anchor" href="#The-REPL-Pane" aria-label="Permalink to &quot;The REPL Pane {#The-REPL-Pane}&quot;">​</a></h2><p><em>Bottom drawer — <code>Ctrl+J</code>.</em> The REPL pane is a <strong>persistent Julia session</strong> available throughout a session: the same bindings, the same loaded packages — but its output is structured, and the figures it produces render <strong>inline in the native window</strong> rather than as terminal text. It shares the bottom drawer slot with the <a href="/ship-of-tools/dev/guide/interface#The-Terminal-Drawer">Terminal</a> and <a href="/ship-of-tools/dev/guide/interface#The-Monitor-Drawer">Monitor</a>.</p><p>This page covers the pane itself — what fills it, its keys, how to drive it. For the frame schema, dispatch semantics, and figure-rendering mechanics in depth, see <a href="./repl">The REPL</a>.</p>',3)),o(i,{name:"repl-figure",caption:"The Julia drawer after running scripts/route.jl: the printed output and the figure inline."}),e[9]||(e[9]=r('<h3 id="What-fills-it-4" tabindex="-1">What fills it <a class="header-anchor" href="#What-fills-it-4" aria-label="Permalink to &quot;What fills it {#What-fills-it-4}&quot;">​</a></h3><p>A Julia process <strong>supervised by the backend daemon</strong>, distinct from the kernel that does project introspection. They are separate on purpose: the kernel owns dispatch tables, mode trees, indexing, and AST hashing; the REPL owns your interactive state. Because they are different processes, <strong>killing the REPL does not kill the kernel</strong> — you can restart your interactive session to clear state or recover from a wedged computation without losing the project view.</p><h3 id="Driving-it-2" tabindex="-1">Driving it <a class="header-anchor" href="#Driving-it-2" aria-label="Permalink to &quot;Driving it {#Driving-it-2}&quot;">​</a></h3><p>Two ways to drive it, without retyping:</p><ul><li><p><strong>Run a <code>.jl</code> file</strong> from Files mode — <code>Shift+R</code> <code>include</code>s it into the current session; <code>r</code> first resets the REPL into the file&#39;s own project, then runs it.</p></li><li><p><strong>Type at the prompt</strong> — <code>Enter</code> submits, <code>Shift+Enter</code> inserts a newline.</p></li></ul><p>Per-line and per-block dispatch (the line at the cursor, or the surrounding top-level form) are <strong>planned</strong>, not yet built.</p><p>A long-running evaluation runs on its own task, so it does not block the dispatch loop and you can interrupt it mid-eval — a real <code>InterruptException</code>, the same as <code>Ctrl-C</code> in the stock REPL.</p><h3 id="Structured-output" tabindex="-1">Structured output <a class="header-anchor" href="#Structured-output" aria-label="Permalink to &quot;Structured output {#Structured-output}&quot;">​</a></h3><p>Instead of one undifferentiated text stream, the display shim emits <strong>typed frames</strong> — <code>stdout</code>, <code>stderr</code>, <code>value</code>, <code>image</code>, <code>error</code>, and a terminal <code>done</code> — so the frontend renders each correctly: <code>stdout</code>/<code>stderr</code> stream as bytes arrive, errors carry a structured stacktrace with <code>file:line</code> links, and a showable value (a CairoMakie <code>Figure</code>, a <code>Plots.Plot</code>, anything with <code>show(io, MIME&quot;image/png&quot;)</code>) becomes an <code>image</code> frame <strong>drawn inline through the preview layer</strong> — never a degraded terminal-graphics protocol.</p><h2 id="The-Terminal-Drawer" tabindex="-1">The Terminal Drawer <a class="header-anchor" href="#The-Terminal-Drawer" aria-label="Permalink to &quot;The Terminal Drawer {#The-Terminal-Drawer}&quot;">​</a></h2><p><em>Bottom drawer — <code>Ctrl+T</code>.</em> The Terminal is a <strong>local OS shell on the frontend machine</strong>. Its canonical use is SSHing outward to backend hosts, and because it is local — <strong>not</strong> proxied through the daemon — it works even when the backend is unreachable. It shares the bottom drawer slot with the <a href="/ship-of-tools/dev/guide/interface#The-REPL-Pane">REPL</a> (<code>Ctrl+J</code>) and the <a href="/ship-of-tools/dev/guide/interface#The-Monitor-Drawer">Monitor</a> (<code>Ctrl+M</code>): each key toggles its own content, and pressing another swaps it in place.</p><p><code>Ctrl+T</code> opens the Terminal drawer, a shell in the project root.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Drawer closed</th><th style="text-align:right;">Showing this content</th><th style="text-align:right;">Showing other content</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Ctrl+T</code></td><td style="text-align:right;">→ Terminal</td><td style="text-align:right;">→ closed</td><td style="text-align:right;">→ Terminal</td></tr><tr><td style="text-align:right;"><code>Ctrl+J</code></td><td style="text-align:right;">→ REPL</td><td style="text-align:right;">→ closed</td><td style="text-align:right;">→ REPL</td></tr></tbody></table><h3 id="Scrollback" tabindex="-1">Scrollback <a class="header-anchor" href="#Scrollback" aria-label="Permalink to &quot;Scrollback {#Scrollback}&quot;">​</a></h3><p>Plain <code>PgUp</code>/<code>PgDn</code> page the drawer&#39;s scrollback ring (a one-third-pane step, the same convention as the LLM pane) — so a <code>claude</code> session running here scrolls exactly like one in the LLM pane. Typing snaps back to the live tail. Two escape hatches keep full-screen apps working:</p><ul><li><p>Apps on the <strong>alternate screen</strong> (<code>vim</code>, <code>less</code>) page themselves — they receive the raw key automatically.</p></li><li><p><code>Shift+PgUp</code>/<code>Shift+PgDn</code> forwards a plain <code>PgUp</code>/<code>PgDn</code> to a primary-screen app that wants the key itself.</p></li></ul><p>The mouse wheel scrolls the same ring, or is forwarded as SGR mouse events when the running app has enabled mouse tracking (<code>vim</code>, <code>htop</code>).</p><h2 id="The-Monitor-Drawer" tabindex="-1">The Monitor Drawer <a class="header-anchor" href="#The-Monitor-Drawer" aria-label="Permalink to &quot;The Monitor Drawer {#The-Monitor-Drawer}&quot;">​</a></h2><p><em>Bottom drawer — <code>Ctrl+M</code>.</em> The Monitor shows <strong>CPU / GPU / RAM history across all your hosts at once</strong> — small-multiples, one compact panel per host (a multi-GPU box shows each GPU as its own trace). It shares the bottom drawer slot with the <a href="/ship-of-tools/dev/guide/interface#The-REPL-Pane">REPL</a> (<code>Ctrl+J</code>) and the <a href="/ship-of-tools/dev/guide/interface#The-Terminal-Drawer">Terminal</a> (<code>Ctrl+T</code>); the toggle is global, so it opens even when another pane has focus.</p><h3 id="How-it-gets-the-data" tabindex="-1">How it gets the data <a class="header-anchor" href="#How-it-gets-the-data" aria-label="Permalink to &quot;How it gets the data {#How-it-gets-the-data}&quot;">​</a></h3><p>The declared <strong>hub</strong> is the aggregator: it alone runs the <code>[monitor]</code> roster, and the drawer subscribes to the hub regardless of which host you&#39;re navigating — &quot;see all servers at once&quot; is solved at the data layer, on the one daemon that&#39;s the monitoring authority. For each host in the roster the hub runs a small sampler:</p><ul><li><p><strong>its own host</strong> locally; <strong>remote hosts</strong> as <code>ssh &lt;alias&gt; bash -s</code>, with the script fed over stdin — <strong>zero footprint</strong>, no daemon, nothing written to the remote&#39;s disk.</p></li><li><p>CPU% from <code>/proc/stat</code>, RAM% from <code>/proc/meminfo</code>, GPU from <code>nvidia-smi</code>. All world-readable, so <strong>no sudo and no privileges</strong> are needed.</p></li></ul><p>A daemon that is <strong>not</strong> the hub samples only the host it runs on — it never ssh&#39;s anywhere, so a wrong or unreachable alias on some other box can&#39;t wedge it. Dialling a non-hub daemon directly shows that daemon&#39;s own single panel, not the fleet; to see the fleet, dial the hub.</p><p>Sampling is <strong>always on</strong> for the life of the daemon, so the drawer shows real history the moment it opens rather than starting from a blank axis; what <code>monitor.subscribe</code> gates is per-connection <em>delivery</em> of ticks, not collection. (ADR 0020 originally specified reactive spawn-on-subscribe; the implementation went the other way and the ADR carries a note.) The hub keeps an in-memory tiered ring buffer per host, so the time axis can rescale to wider windows without a round-trip. Restarting the hub restarts that history.</p><p>Which hosts appear comes from the <code>[monitor]</code> section of <code>~/.config/sot/hosts.toml</code> (or the file <code>$SOT_HOSTS</code> names); see <a href="./../ref/config">Configuration Files</a>. With no <code>[monitor]</code> section, or on a non-hub daemon, only that daemon&#39;s own host is sampled; the <code>[host.*]</code> entries are frontend connection targets and are not monitored implicitly.</p><p><strong>The list binds when the daemon starts.</strong> Editing <code>hosts.toml</code> while the hub is running changes nothing until it restarts — there is no reload and no file watch. If the drawer is missing a host you just added, restart the hub.</p><h3 id="On-philosophy-rendering" tabindex="-1">On-philosophy rendering <a class="header-anchor" href="#On-philosophy-rendering" aria-label="Permalink to &quot;On-philosophy rendering {#On-philosophy-rendering}&quot;">​</a></h3><p>Traces are drawn as <strong>real SVG</strong>, rasterized through the same <code>resvg</code> → wgpu-quad pipeline that renders typeset math — not braille/cell plotting, which is the same class of degraded hack the project rejects for images. A host whose SSH or sampler dies renders an explicit <strong>gap</strong>, never a silent flatline or a quiet fallback to &quot;looks fine.&quot;</p>',28))])}const T=d(c,[["render",g]]);export{b as __pageData,T as default};
